"""The per-utterance speech synthesis recorder and its factories."""

from __future__ import annotations

import time
from contextvars import ContextVar
from typing import TYPE_CHECKING, Optional

from opentelemetry import trace
from opentelemetry.trace import Span

from rasa.tracing.voice.metrics import (
    InteractionOutcome,
    VoiceComponent,
    VoiceOperation,
    record_operation_failure_metric,
    record_tts_synthesis_duration_metric,
    record_tts_time_to_first_audio_metric,
)
from rasa.tracing.voice.recorders.tts.span_attributes import engine_attributes
from rasa.tracing.voice.shared import semconv
from rasa.tracing.voice.spans import (
    content_capture_enabled,
    set_span_error,
    start_voice_span,
    voice_observability_enabled,
)

if TYPE_CHECKING:
    from rasa.core.channels.voice_stream.tts.tts_engine import TTSEngine


class SynthesizeSpeechRecorder:
    """Record spans and metrics for one synthesized message.

    Each message has its own recorder, even when a turn speaks more than one
    message. The span covers the entire utterance lifecycle, from recorder
    creation until :meth:`end`. Metrics use a separate timing window. The first
    call to :meth:`record_request`, or to :meth:`record_cache_hit` with ``True``,
    opens that window; later calls do not reset it. Without either anchor, the
    recorder still adds span events but emits no duration histograms or
    first-byte latency attribute.

    A detached recorder ignores both spans and metrics, allowing callers to
    record without checking whether an utterance is active.

    Args:
        span: Span for this utterance. Non-recording in metrics-only mode;
            span writes are skipped while metric bookkeeping still runs.
        tts_provider_name: Name of the TTS provider serving this utterance,
            as reported by ``TTSEngine.name()`` (e.g. ``"azure"``,
            ``"deepgram"``). Stamped on the utterance's duration and failure
            metrics as the ``provider`` attribute.
    """

    def __init__(self, span: Span, *, tts_provider_name: Optional[str] = None) -> None:
        # Identity: what this recorder describes and whether it is live.
        self.span = span
        self._tts_provider_name = tts_provider_name
        self._emit_metrics = True
        self._text = ""
        # Exclude work before the first provider request or cache hit from metrics.
        self._started_monotonic: Optional[float] = None
        self._first_audio_elapsed_s: Optional[float] = None
        self._completion_elapsed_s: Optional[float] = None
        self._error_elapsed_s: Optional[float] = None
        # Terminal state: metric attributes and emission guards.
        self._cache_hit: Optional[bool] = None
        self._failed = False
        # Ensure terminal metrics are processed at most once per recorder.
        self._terminal_metrics_finalized = False
        # Generated-audio totals: stamped on the span at end().
        self._audio_bytes_total = 0
        self._audio_chunk_count = 0

    @classmethod
    def detached(cls) -> "SynthesizeSpeechRecorder":
        """Return a recorder that emits neither spans nor metrics."""
        recorder = cls(trace.INVALID_SPAN)
        recorder._emit_metrics = False
        return recorder

    def record_request(self) -> None:
        """Record a synthesis request to the TTS provider.

        The first provider request or cache hit opens the metric timing window.
        Later anchors do not reset it. Starting here keeps channel work, such as
        preparing the engine or sending a start marker, out of provider-latency
        metrics.
        """
        if self._started_monotonic is None:
            self._started_monotonic = time.monotonic()
        if self.span.is_recording():
            self.span.add_event(semconv.EVENT_TTS_REQUEST)

    def record_first_audio(self) -> None:
        """Record the first generated audio chunk for this utterance.

        After an anchor, this captures the elapsed time to first audio and
        stores it on the span. Without an anchor, it adds the span event but
        records no latency. The event is tagged with the audio source
        (cached, generated, or fallback). The turn context separately tracks
        the first audio across the whole turn for user-perceived latency.
        """
        if self._first_audio_elapsed_s is None and self._started_monotonic is not None:
            self._first_audio_elapsed_s = time.monotonic() - self._started_monotonic
        if self.span.is_recording():
            self.span.add_event(
                semconv.EVENT_TTS_FIRST_AUDIO_GENERATED,
                attributes={semconv.VOICE_TTS_AUDIO_SOURCE: self._audio_source()},
            )
            if self._first_audio_elapsed_s is not None:
                self.span.set_attribute(
                    semconv.VOICE_LATENCY_TTS_FIRST_BYTE_MS,
                    self._first_audio_elapsed_s * 1000,
                )

    def record_complete(self) -> None:
        """Record the completion of audio generation for this utterance.

        This captures a completion duration only after a provider request or
        cache hit has opened the metric timing window.
        """
        if self._completion_elapsed_s is None and self._started_monotonic is not None:
            self._completion_elapsed_s = time.monotonic() - self._started_monotonic
        if self.span.is_recording():
            self.span.add_event(semconv.EVENT_TTS_COMPLETE)

    def record_error(self, error: BaseException) -> None:
        """Record a TTS failure and mark the span ERROR (the span stays open).

        The first error increments the failure counter and becomes the
        utterance's terminal time. It also suppresses first-audio latency
        because audio produced after a failure is the silence fallback, not
        synthesized speech. An anchored recorder captures the error duration;
        an unanchored recorder still increments the failure counter.
        """
        if not self._failed:
            if self._started_monotonic is not None:
                self._error_elapsed_s = time.monotonic() - self._started_monotonic
            if self._emit_metrics:
                record_operation_failure_metric(
                    component=VoiceComponent.TTS,
                    operation=VoiceOperation.SYNTHESIZE,
                    error=error,
                    provider=self._tts_provider_name,
                )
        self._failed = True
        if self.span.is_recording():
            self.span.add_event(semconv.EVENT_TTS_ERROR)
            set_span_error(self.span, error)

    def record_cache_hit(self, cache_hit: bool) -> None:
        """Record whether the utterance's audio came from the TTS cache.

        A cache hit opens the metric timing window unless a provider request
        already opened it. This makes cached durations represent cached audio
        delivery and tags them with ``cache_hit=true``. A cache miss
        never opens the window; the provider request that follows does.
        Cache hits also emit ``voice.tts_cache_hit`` because they have no
        corresponding TTS request event.
        """
        if cache_hit and self._started_monotonic is None:
            self._started_monotonic = time.monotonic()
        self._cache_hit = cache_hit
        if self.span.is_recording():
            self.span.set_attribute(semconv.VOICE_TTS_CACHE_HIT, cache_hit)
            if cache_hit:
                self.span.add_event(semconv.EVENT_TTS_CACHE_HIT)

    def record_text(self, text: str) -> None:
        """Stamp the synthesized text, only when content capture is enabled."""
        self._text = text
        if self.span.is_recording() and content_capture_enabled():
            self.span.set_attribute(semconv.VOICE_TTS_TEXT, text)

    def append_text(self, text: str) -> None:
        """Append a provider-bound streaming chunk to the synthesized text."""
        self.record_text(self._text + text)

    @property
    def text(self) -> str:
        """Return the text submitted to the TTS provider so far."""
        return self._text

    def record_audio_chunk(self, num_bytes: int) -> None:
        """Count one generated audio chunk; totals are stamped at :meth:`end`."""
        self._audio_bytes_total += num_bytes
        self._audio_chunk_count += 1

    def end(self) -> None:
        """End the utterance span, stamp its totals, and emit duration metrics."""
        if self.span.is_recording():
            self.span.set_attribute(semconv.AUDIO_BYTES_TOTAL, self._audio_bytes_total)
            self.span.set_attribute(semconv.AUDIO_CHUNK_COUNT, self._audio_chunk_count)
        self._emit_duration_metrics()
        # Ending and contextvar cleanup must run even when the span never
        # recorded, or the stale recorder would be reused for the next
        # utterance.
        self.span.end()
        _current_synthesis_recorder.set(None)

    def _audio_source(self) -> str:
        """Return the utterance's audio source.

        A cache hit takes precedence. Otherwise, audio after a failure is
        fallback; all other audio is generated.
        """
        if self._cache_hit:
            return semconv.TTS_AUDIO_SOURCE_CACHED
        if self._failed:
            return semconv.TTS_AUDIO_SOURCE_FALLBACK
        return semconv.TTS_AUDIO_SOURCE_GENERATED

    def _emit_duration_metrics(self) -> None:
        """Emit the utterance's duration histograms at most once.

        Emission is deferred until :meth:`end` so the cache state is known
        regardless of when the channel recorded it. A failed synthesis emits an
        error-tagged duration from the anchor to the first failure, but no
        first-audio latency because later audio is the silence fallback. An
        unanchored recorder has no duration to emit.
        """
        if not self._emit_metrics or self._terminal_metrics_finalized:
            return
        self._terminal_metrics_finalized = True
        if self._failed:
            if self._error_elapsed_s is not None:
                record_tts_synthesis_duration_metric(
                    self._error_elapsed_s,
                    outcome=InteractionOutcome.ERROR,
                    provider=self._tts_provider_name,
                    cache_hit=self._cache_hit,
                )
            return
        if self._first_audio_elapsed_s is not None:
            record_tts_time_to_first_audio_metric(
                self._first_audio_elapsed_s,
                provider=self._tts_provider_name,
                cache_hit=self._cache_hit,
            )
        if self._completion_elapsed_s is not None:
            record_tts_synthesis_duration_metric(
                self._completion_elapsed_s,
                outcome=InteractionOutcome.COMPLETED,
                provider=self._tts_provider_name,
                cache_hit=self._cache_hit,
            )


_current_synthesis_recorder: ContextVar[Optional[SynthesizeSpeechRecorder]] = (
    ContextVar("rasa_voice_synthesis", default=None)
)


def get_or_create_synthesize_speech_recorder(
    engine: "TTSEngine",
) -> SynthesizeSpeechRecorder:
    """Return the open utterance's recorder or create one for a new utterance.

    Reuses the active recorder when synthesis is already in progress. A new
    recorder opens a `synthesize speech` span with the ambient span as its
    parent. In metrics-only mode the
    recorder wraps a non-recording span but is still bound and tracked; when
    voice observability is fully disabled, a detached no-op recorder is
    returned without being bound.
    """
    if not voice_observability_enabled():
        return SynthesizeSpeechRecorder.detached()

    synthesis_recorder = _current_synthesis_recorder.get()
    if synthesis_recorder is not None:
        return synthesis_recorder
    span = start_voice_span(
        semconv.SPAN_NAME_SYNTHESIZE_SPEECH, attributes=engine_attributes(engine)
    )
    synthesis_recorder = SynthesizeSpeechRecorder(span, tts_provider_name=engine.name())
    _current_synthesis_recorder.set(synthesis_recorder)
    return synthesis_recorder


def get_current_synthesize_speech_recorder() -> SynthesizeSpeechRecorder:
    """Return the open utterance's recorder.

    Between utterances (and when tracing is disabled) returns a detached
    no-op recorder, so callers can record unconditionally.
    """
    synthesis_recorder = _current_synthesis_recorder.get()
    if synthesis_recorder is not None:
        return synthesis_recorder
    return SynthesizeSpeechRecorder.detached()
